CREATE DATABASE IF NOT EXISTS campus_food_prebooking;
USE campus_food_prebooking;

DROP TABLE IF EXISTS chat_messages;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS students;
DROP TABLE IF EXISTS menu_items;
DROP TABLE IF EXISTS stalls;

CREATE TABLE stalls (
  id VARCHAR(50) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  cuisine VARCHAR(100) NOT NULL,
  rating DECIMAL(3, 2),
  preparation_time_est INT,
  busy_slots TEXT
);

CREATE TABLE menu_items (
  id VARCHAR(50) PRIMARY KEY,
  stall_id VARCHAR(50),
  name VARCHAR(100) NOT NULL,
  price DECIMAL(10, 2) NOT NULL,
  category VARCHAR(50),
  description TEXT,
  inventory INT,
  popularity DECIMAL(3, 2),
  is_available BOOLEAN,
  FOREIGN KEY (stall_id) REFERENCES stalls(id) ON DELETE CASCADE
);

CREATE TABLE students (
  registration_number VARCHAR(50) PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  phone VARCHAR(20) NOT NULL,
  balance DECIMAL(10, 2) DEFAULT 0.00
);

CREATE TABLE orders (
  id VARCHAR(50) PRIMARY KEY,
  stall_id VARCHAR(50),
  stall_name VARCHAR(100) NOT NULL,
  registration_number VARCHAR(50),
  total_amount DECIMAL(10, 2) NOT NULL,
  pickup_time VARCHAR(20) NOT NULL,
  pickup_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL,
  estimated_ready_time VARCHAR(20),
  created_at VARCHAR(50) NOT NULL,
  payment_status VARCHAR(20) NOT NULL,
  payment_method VARCHAR(20) NOT NULL,
  transaction_id VARCHAR(50),
  waiting_time_estimation INT,
  FOREIGN KEY (stall_id) REFERENCES stalls(id),
  FOREIGN KEY (registration_number) REFERENCES students(registration_number)
);

CREATE TABLE order_items (
  id INT AUTO_INCREMENT PRIMARY KEY,
  order_id VARCHAR(50),
  item_id VARCHAR(50),
  name VARCHAR(100) NOT NULL,
  price DECIMAL(10, 2) NOT NULL,
  quantity INT NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE
);

CREATE TABLE chat_messages (
  id VARCHAR(100) PRIMARY KEY,
  registration_number VARCHAR(50),
  sender VARCHAR(20) NOT NULL,
  text TEXT NOT NULL,
  timestamp VARCHAR(20) NOT NULL,
  metadata TEXT
);

